<template><section v-if="entry" class="docker-tooling"><header><div><small>Docker / CLI 证据</small><h2 id="docker-tools">{{entry.name}} 连接与查询</h2></div><b :data-status="entry.status">{{label}}</b></header><p v-if="entry.note">{{entry.note}}</p><div class="facts"><div><span>运行模式</span><strong>{{entry.mode}}</strong></div><div><span>镜像锁</span><strong>{{entry.images.map(image=>`${image.role}: ${image.digestKey||image.tag}`).join(' · ')||'不适用'}}</strong></div><div><span>关键 CLI</span><strong>{{entry.keyTools.join(' · ')||'浏览器 API'}}</strong></div><div><span>连接</span><code>{{entry.connectCommand}}</code></div><div class="wide"><span>查询会话</span><code>{{entry.queryCommand}}</code></div></div><p v-if="!complete&&entry.status!=='unsupported'" class="pending">真实 Docker 快照尚待手动工作流采集；当前只展示采集规格，不冒充实测结果。</p><details v-for="x in evidence" :key="x.kind" v-show="x.text"><summary>{{x.label}}</summary><pre>{{x.text}}</pre></details></section></template>
<script setup lang="ts">import{computed}from'vue';import{dockerCatalogById}from'../data/dockerCatalog';import{dockerEvidence}from'../data/dockerEvidence';const p=defineProps<{product:string}>();const entry=computed(()=>dockerCatalogById[p.product]);const evidence=computed(()=>[{kind:'inventory',label:'镜像与完整工具清单',text:dockerEvidence(p.product,'inventory')},{kind:'session',label:'连接与查询会话',text:dockerEvidence(p.product,'session')},{kind:'assert',label:'断言结果',text:dockerEvidence(p.product,'assert')}]);const complete=computed(()=>evidence.value.every(x=>/status:\s*verified/.test(x.text)));const label=computed(()=>complete.value?'已验证':({verified:'已验证',partial:'部分验证',documented:'待首次采集',unsupported:'不适用'}[entry.value?.status||'documented']))</script>
<style scoped>.docker-tooling{margin:2rem 0;padding:1rem;border:1px solid var(--vp-c-divider);border-radius:14px;background:var(--vp-c-bg-soft)}header{display:flex;justify-content:space-between;gap:1rem}h2{margin:.2rem 0;border:0}small{color:var(--vp-c-brand-1);font-weight:800}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem}.facts>div{display:grid;gap:.25rem;padding:.65rem;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg)}.wide{grid-column:1/-1}span,.pending{color:var(--vp-c-text-2)}strong,code{overflow-wrap:anywhere}pre{max-height:28rem;overflow:auto}@media(max-width:700px){.facts{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
